import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const b=JSON.parse('{"title":"Προσχέδια που λείπουν και σφάλματα πακέτων","description":"","frontmatter":{},"headers":[],"relativePath":"el/help/website-draft-problems.md","filePath":"el/help/website-draft-problems.md"}'),s={name:"el/help/website-draft-problems.md"};function l(i,e,h,n,c,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="προσχεδια-που-λειπουν-και-σφαλματα-πακετων" tabindex="-1">Προσχέδια που λείπουν και σφάλματα πακέτων <a class="header-anchor" href="#προσχεδια-που-λειπουν-και-σφαλματα-πακετων" aria-label="Permalink to &quot;Προσχέδια που λείπουν και σφάλματα πακέτων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Εκπαιδευτικό προσχέδιο βάσει πηγαίου κώδικα · TransferBook+ v0.7.9. Επιβεβαιώστε έκδοση, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα. Δεν τεκμαίρεται ζωντανή ενεργοποίηση.</p></div><h2 id="το-προσχεδιο-της-ιστοσελιδας-εξαφανιστηκε" tabindex="-1">Το προσχέδιο της ιστοσελίδας εξαφανίστηκε <a class="header-anchor" href="#το-προσχεδιο-της-ιστοσελιδας-εξαφανιστηκε" aria-label="Permalink to &quot;Το προσχέδιο της ιστοσελίδας εξαφανίστηκε&quot;">​</a></h2><p>Ελέγξτε browser, προφίλ, εταιρεία και τρόπο λειτουργίας κατά την αποθήκευση. Τα τοπικά προσχέδια έχουν καθορισμένο πεδίο. Παλαιότερα προσχέδια χωρίς πεδίο δεν μεταφέρονται αυτόματα. Μην διαγράφετε την αποθήκευση του browser όσο εκκρεμεί ανάκτηση.</p><h2 id="δεν-εισαγεται-το-πακετο" tabindex="-1">Δεν εισάγεται το πακέτο <a class="header-anchor" href="#δεν-εισαγεται-το-πακετο" aria-label="Permalink to &quot;Δεν εισάγεται το πακέτο&quot;">​</a></h2><p>Ελέγξτε αν επιλέξατε συμβατό <code>.tbsite.json</code> ή <code>.tbtheme.json</code>. Ασυμφωνία checksum, ασύμβατο σχήμα ή μη ασφαλές περιεχόμενο μπορεί να εμποδίσει την εισαγωγή. Εξαγάγετε ξανά από το αρχικό περιβάλλον αντί να αλλάξετε χειροκίνητα το checksum.</p><h2 id="γιατι-ειναι-κλειδωμενη-η-δημοσιευση" tabindex="-1">Γιατί είναι κλειδωμένη η δημοσίευση; <a class="header-anchor" href="#γιατι-ειναι-κλειδωμενη-η-δημοσιευση" aria-label="Permalink to &quot;Γιατί είναι κλειδωμένη η δημοσίευση;&quot;">​</a></h2><p>Έγκυρο προσχέδιο ή έγκριση δεν αποδεικνύει άδεια δημόσιας δημοσίευσης. Ελέγξτε την ενεργοποίηση και τα δικαιώματα με διαχειριστή. Η βιβλιοθήκη προτύπων μπορεί επίσης να έχει περιορισμένη αποθήκευση σε λειτουργία συμβατότητας.</p><h2 id="ελεγχος-ανακτησης" tabindex="-1">Έλεγχος ανάκτησης <a class="header-anchor" href="#ελεγχος-ανακτησης" aria-label="Permalink to &quot;Έλεγχος ανάκτησης&quot;">​</a></h2><p>Κρατήστε την αρχική εξαγωγή, σημειώστε την έκδοση και το σφάλμα επικύρωσης χωρίς εμπιστευτικό περιεχόμενο. Ανακτήστε από το αρχικό περιβάλλον browser, αν υπάρχει. Μην αντιγράφετε κλειδιά αποθήκευσης μεταξύ εταιρειών.</p><p>Δείτε <a href="/el/websites/draft-storage.html">Τοπικά προσχέδια</a> και <a href="/el/websites/template-manager.html">Template Manager</a>.</p><h2 id="ανακτηση-και-φιλοξενια-σε-νεοτερες-εκδοσεις-staging" tabindex="-1">Ανάκτηση και φιλοξενία σε νεότερες εκδόσεις staging <a class="header-anchor" href="#ανακτηση-και-φιλοξενια-σε-νεοτερες-εκδοσεις-staging" aria-label="Permalink to &quot;Ανάκτηση και φιλοξενία σε νεότερες εκδόσεις staging&quot;">​</a></h2><p>Στη v0.7.10, ελέγξτε την ειδοποίηση ανάκτησης αυτόματης αποθήκευσης και χρησιμοποιήστε πλήρες αντίγραφο χώρου εργασίας όπου διατίθεται. Επαναφέρετε στη σωστή εταιρεία και τρόπο λειτουργίας, αποθηκεύστε ρητά και επιβεβαιώστε. Δείτε <a href="/el/websites/draft-storage.html">Τοπικά προσχέδια και ανάκτηση</a>.</p><p>Στη v0.7.11, η απουσία πάνελ φιλοξενίας ή κλειδωμένο εργαλείο ενημέρωσης μπορεί να οφείλεται στην απενεργοποιημένη από προεπιλογή δοκιμαστική δυνατότητα, στο εταιρικό περιβάλλον ή στα δικαιώματα. Προετοιμασμένη αναθεώρηση δεν σημαίνει ότι άλλαξε η δημόσια ιστοσελίδα. Αν το αποτέλεσμα εξουσιοδοτημένης ενημέρωσης ή επαναφοράς είναι αβέβαιο, μην επαναλάβετε: ζητήστε από τον ιδιοκτήτη έλεγχο αποτυπωμάτων αναθεωρήσεων και αρχείων ανάκτησης. Δείτε <a href="/el/websites/publication-controls.html">Ελέγχους δημοσίευσης</a>.</p>',14)])])}const m=a(s,[["render",l]]);export{b as __pageData,m as default};
